// MyApp.Domain/Entities/Order.cs
public class Order : BaseEntity, IAggregateRoot
{
    public OrderId Id { get; private set; }
    public CustomerId CustomerId { get; private set; }
    public OrderStatus Status { get; private set; }
    private readonly List<OrderItem> _items = new();
    public IReadOnlyCollection<OrderItem> Items => _items.AsReadOnly();
    public decimal Total => _items.Sum(i => i.Price * i.Quantity);

    private Order() { } // EF Core

    public static Order Create(CustomerId customerId, IEnumerable<OrderItemData> items)
    {
        var order = new Order
        {
            Id = OrderId.New(),
            CustomerId = customerId,
            Status = OrderStatus.Pending
        };
        foreach (var item in items)
            order.AddItem(item.ProductId, item.Quantity, item.UnitPrice);

        order.AddDomainEvent(new OrderCreatedEvent(order.Id, order.CustomerId, order.Total));
        return order;
    }

    public void AddItem(ProductId productId, int quantity, decimal unitPrice)
    {
        if (Status != OrderStatus.Pending) throw new InvalidOperationException("Cannot modify confirmed order");
        _items.Add(new OrderItem(productId, quantity, unitPrice));
    }

    public void Confirm()
    {
        if (Status != OrderStatus.Pending) throw new InvalidOperationException("Only pending orders can be confirmed");
        if (!_items.Any()) throw new InvalidOperationException("Order must have items");
        Status = OrderStatus.Confirmed;
        AddDomainEvent(new OrderConfirmedEvent(Id, CustomerId, Total));
    }
}

// MyApp.Domain/ValueObjects/OrderId.cs
public readonly record struct OrderId(Guid Value)
{
    public static OrderId New() => new(Guid.CreateVersion7()); // UUID v7 (time-ordered)
    public static implicit operator Guid(OrderId id) => id.Value;
    public static explicit operator OrderId(Guid guid) => new(guid);
    public override string ToString() => Value.ToString();
}

// MyApp.Domain/Exceptions/DomainException.cs
public abstract class DomainException : Exception
{
    public string Code { get; }
    protected DomainException(string code, string message) : base(message) => Code = code;
}

public class InsufficientStockException : DomainException
{
    public InsufficientStockException(ProductId productId, int requested, int available)
        : base("INSUFFICIENT_STOCK", $"Product {productId}: requested {requested}, available {available}") { }
}

// MyApp.Application/Commands/CreateOrder/CreateOrderCommand.cs
public record CreateOrderCommand(CustomerId CustomerId, List<OrderItemDto> Items) : IRequest<Result<OrderDto>>;

public record OrderItemDto(ProductId ProductId, int Quantity);

// Handler
public class CreateOrderHandler : IRequestHandler<CreateOrderCommand, Result<OrderDto>>
{
    private readonly IOrderRepository _orders;
    private readonly IProductRepository _products;
    private readonly IUnitOfWork _unitOfWork;
    private readonly ILogger<CreateOrderHandler> _log;

    public CreateOrderHandler(IOrderRepository orders, IProductRepository products, IUnitOfWork uow, ILogger<CreateOrderHandler> log)
        => (_orders, _products, _unitOfWork, _log) = (orders, products, uow, log);

    public async Task<Result<OrderDto>> Handle(CreateOrderCommand request, CancellationToken ct)
    {
        // Проверка товаров и резервирование
        foreach (var item in request.Items)
        {
            var product = await _products.GetByIdAsync(item.ProductId, ct)
                ?? throw new NotFoundException($"Product {item.ProductId} not found");
            if (product.Stock < item.Quantity)
                throw new InsufficientStockException(item.ProductId, item.Quantity, product.Stock);
            product.ReserveStock(item.Quantity);
        }

        var order = Order.Create(request.CustomerId, request.Items);
        await _orders.AddAsync(order, ct);
        await _unitOfWork.SaveChangesAsync(ct);

        _log.LogInformation("Order {OrderId} created for customer {CustomerId}", order.Id, request.CustomerId);
        return Result.Success(order.ToDto());
    }
}

// MyApp.Application/Queries/GetOrder/GetOrderQuery.cs
public record GetOrderQuery(OrderId Id) : IRequest<Result<OrderDetailDto>>;

public class GetOrderHandler : IRequestHandler<GetOrderQuery, Result<OrderDetailDto>>
{
    private readonly IReadOnlyOrderRepository _orders; // отдельный read-only репозиторий

    public GetOrderHandler(IReadOnlyOrderRepository orders) => _orders = orders;

    public async Task<Result<OrderDetailDto>> Handle(GetOrderQuery request, CancellationToken ct)
    {
        var order = await _orders.GetDetailAsync(request.Id, ct);
        return order == null ? Result.Failure<OrderDetailDto>(Error.NotFound) : Result.Success(order);
    }
}

// Validation Behavior
public class ValidationBehavior<TRequest, TResponse> : IPipelineBehavior<TRequest, TResponse>
    where TRequest : IRequest<TResponse>
{
    private readonly IEnumerable<IValidator<TRequest>> _validators;
    public ValidationBehavior(IEnumerable<IValidator<TRequest>> validators) => _validators = validators;

    public async Task<TResponse> Handle(TRequest request, RequestHandlerDelegate<TResponse> next, CancellationToken ct)
    {
        var context = new ValidationContext<TRequest>(request);
        var failures = _validators.Select(v => v.Validate(context))
            .SelectMany(r => r.Errors).Where(f => f != null).ToList();

        if (failures.Any()) throw new ValidationException(failures);
        return await next(ct);
    }
}

// Logging Behavior
public class LoggingBehavior<TRequest, TResponse> : IPipelineBehavior<TRequest, TResponse>
{
    private readonly ILogger<LoggingBehavior<TRequest, TResponse>> _log;
    public LoggingBehavior(ILogger<LoggingBehavior<TRequest, TResponse>> log) => _log = log;

    public async Task<TResponse> Handle(TRequest request, RequestHandlerDelegate<TResponse> next, CancellationToken ct)
    {
        _log.LogInformation("Handling {RequestType}", typeof(TRequest).Name);
        var response = await next(ct);
        _log.LogInformation("Handled {RequestType}", typeof(TRequest).Name);
        return response;
    }
}

// Transaction Behavior (для команд)
public class TransactionBehavior<TRequest, TResponse> : IPipelineBehavior<TRequest, TResponse>
    where TRequest : IRequest<TResponse>
{
    private readonly IUnitOfWork _uow;
    public TransactionBehavior(IUnitOfWork uow) => _uow = uow;

    public async Task<TResponse> Handle(TRequest request, RequestHandlerDelegate<TResponse> next, CancellationToken ct)
    {
        if (request is not ICommand) return await next(ct); // только для команд

        var strategy = _uow.CreateExecutionStrategy();
        return await strategy.ExecuteAsync(async () =>
        {
            await using var tx = await _uow.BeginTransactionAsync(ct);
            try
            {
                var response = await next(ct);
                await tx.CommitAsync(ct);
                return response;
            }
            catch
            {
                await tx.RollbackAsync(ct);
                throw;
            }
        });
    }
}

// MyApp.Application/DependencyInjection.cs
public static class ApplicationServiceExtensions
{
    public static IServiceCollection AddApplication(this IServiceCollection services)
    {
        var assembly = Assembly.GetExecutingAssembly();
        services.AddMediatR(cfg => cfg.RegisterServicesFromAssembly(assembly));
        services.AddValidatorsFromAssembly(assembly);

        services.AddTransient(typeof(IPipelineBehavior<,>), typeof(ValidationBehavior<,>));
        services.AddTransient(typeof(IPipelineBehavior<,>), typeof(LoggingBehavior<,>));
        services.AddTransient(typeof(IPipelineBehavior<,>), typeof(TransactionBehavior<,>));

        return services;
    }
}

// MyApp.Infrastructure/Persistence/Configurations/OrderConfiguration.cs
public class OrderConfiguration : IEntityTypeConfiguration<Order>
{
    public void Configure(EntityTypeBuilder<Order> builder)
    {
        builder.HasKey(o => o.Id);
        builder.Property(o => o.Id).HasConversion(v => v.Value, v => new OrderId(v));
        builder.Property(o => o.CustomerId).HasConversion(v => v.Value, v => new CustomerId(v));
        builder.OwnsMany(o => o.Items, item =>
        {
            item.WithOwner().HasForeignKey("OrderId");
            item.Property(i => i.ProductId).HasConversion(v => v.Value, v => new ProductId(v));
        });
        builder.Property(o => o.Status).HasConversion<string>();
    }
}

// MyApp.Infrastructure/Persistence/AppDbContext.cs
public class AppDbContext : DbContext, IUnitOfWork
{
    public DbSet<Order> Orders => Set<Order>();
    public DbSet<Product> Products => Set<Product>();
    public DbSet<Customer> Customers => Set<Customer>();

    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

    protected override void OnModelCreating(ModelBuilder model)
    {
        model.ApplyConfigurationsFromAssembly(Assembly.GetExecutingAssembly());
        base.OnModelCreating(model);
    }

    public async Task<int> SaveChangesAsync(CancellationToken ct = default)
    {
        // Dispatch domain events before save
        var entities = ChangeTracker.Entries<BaseEntity>()
            .Where(e => e.Entity.DomainEvents.Any()).Select(e => e.Entity).ToList();

        var result = await base.SaveChangesAsync(ct);

        foreach (var entity in entities)
        {
            var events = entity.DomainEvents.ToList();
            entity.ClearDomainEvents();
            // Publish events (через MediatR или отдельный publisher)
        }
        return result;
    }
}

// MyApp.Infrastructure/Persistence/Repositories/OrderRepository.cs
public class OrderRepository : IOrderRepository
{
    private readonly AppDbContext _ctx;
    public OrderRepository(AppDbContext ctx) => _ctx = ctx;

    public async Task AddAsync(Order order, CancellationToken ct) => await _ctx.Orders.AddAsync(order, ct);
    public Task<Order?> GetByIdAsync(OrderId id, CancellationToken ct) => _ctx.Orders.FindAsync([id], ct).AsTask();
    public Task<Order?> GetWithItemsAsync(OrderId id, CancellationToken ct) =>
        _ctx.Orders.Include(o => o.Items).FirstOrDefaultAsync(o => o.Id == id, ct);
}

// Read-only repository (AsNoTracking, проекции)
public class ReadOnlyOrderRepository : IReadOnlyOrderRepository
{
    private readonly AppDbContext _ctx;
    public ReadOnlyOrderRepository(AppDbContext ctx) => _ctx = ctx;

    public async Task<OrderDetailDto?> GetDetailAsync(OrderId id, CancellationToken ct)
        => await _ctx.Orders.AsNoTracking()
            .Where(o => o.Id == id)
            .Select(o => new OrderDetailDto(
                o.Id, o.CustomerId, o.Status, o.Total,
                o.Items.Select(i => new OrderItemDto(i.ProductId, i.Quantity, i.Price)).ToList()))
            .FirstOrDefaultAsync(ct);
}

// MyApp.Api/Endpoints/OrdersEndpoints.cs
public static class OrdersEndpoints
{
    public static void MapOrdersEndpoints(this IEndpointRouteBuilder app)
    {
        var group = app.MapGroup("/api/orders").WithTags("Orders").RequireAuthorization();

        group.MapGet("/", async (ISender sender, [AsParameters] GetOrdersQuery query) =>
            await sender.Send(query))
            .Produces<PagedResult<OrderSummaryDto>>();

        group.MapGet("/{id}", async (OrderId id, ISender sender) =>
        {
            var result = await sender.Send(new GetOrderQuery(id));
            return result.IsSuccess ? Results.Ok(result.Value) : Results.NotFound(result.Error);
        })
        .Produces<OrderDetailDto>()
        .Produces(StatusCodes.Status404NotFound);

        group.MapPost("/", async (CreateOrderCommand command, ISender sender) =>
        {
            var result = await sender.Send(command);
            return result.IsSuccess
                ? Results.Created($"/api/orders/{result.Value.Id}", result.Value)
                : Results.BadRequest(result.Error);
        })
        .Produces<OrderDto>(StatusCodes.Status201Created)
        .ProducesValidationProblem()
        .AddEndpointFilter<ValidationFilter<CreateOrderCommand>>();
    }
}

// MyApp.Api/Middleware/ExceptionHandlingMiddleware.cs
public class ExceptionHandlingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<ExceptionHandlingMiddleware> _log;

    public ExceptionHandlingMiddleware(RequestDelegate next, ILogger<ExceptionHandlingMiddleware> log)
        => (_next, _log) = (next, log);

    public async Task InvokeAsync(HttpContext context)
    {
        try
        {
            await _next(context);
        }
        catch (Exception ex)
        {
            _log.LogError(ex, "Unhandled exception");
            await HandleExceptionAsync(context, ex);
        }
    }

    private static async Task HandleExceptionAsync(HttpContext context, Exception ex)
    {
        var (status, error) = ex switch
        {
            ValidationException v => (StatusCodes.Status400BadRequest, new { Errors = v.Errors.Select(e => e.ErrorMessage) }),
            NotFoundException => (StatusCodes.Status404NotFound, new { Message = ex.Message }),
            DomainException d => (StatusCodes.Status400BadRequest, new { Code = d.Code, Message = ex.Message }),
            _ => (StatusCodes.Status500InternalServerError, new { Message = "Internal server error" })
        };

        context.Response.StatusCode = status;
        context.Response.ContentType = "application/json";
        await context.Response.WriteAsJsonAsync(new { Error = error });
    }
}

