// MyApp.UnitTests/Orders/CreateOrderTests.cs
public class CreateOrderTests
{
    private readonly Mock<IOrderRepository> _orders = new();
    private readonly Mock<IProductRepository> _products = new();
    private readonly Mock<IUnitOfWork> _uow = new();
    private readonly CreateOrderHandler _handler;

    public CreateOrderTests()
    {
        _handler = new CreateOrderHandler(_orders.Object, _products.Object, _uow.Object, Mock.Of<ILogger<CreateOrderHandler>>());
    }

    [Fact]
    public async Task Handle_ValidCommand_CreatesOrder()
    {
        // Arrange
        var productId = ProductId.New();
        _products.Setup(p => p.GetByIdAsync(productId, It.IsAny<CancellationToken>()))
            .ReturnsAsync(new Product(productId, "Widget", 10.00m, 100));

        var command = new CreateOrderCommand(CustomerId.New(), new[] { new OrderItemDto(productId, 2) });

        // Act
        var result = await _handler.Handle(command, CancellationToken.None);

        // Assert
        result.IsSuccess.Should().BeTrue();
        result.Value.Items.Should().HaveCount(1);
        _orders.Verify(o => o.AddAsync(It.IsAny<Order>(), It.IsAny<CancellationToken>()), Times.Once);
        _uow.Verify(u => u.SaveChangesAsync(It.IsAny<CancellationToken>()), Times.Once);
    }
}

// MyApp.IntegrationTests/OrdersEndpointsTests.cs
public class OrdersEndpointsTests : IAsyncLifetime
{
    private readonly PostgreSqlContainer _db = new PostgreSqlBuilder().Build();
    private WebApplicationFactory<Program> _factory;
    private HttpClient _client;

    public async Task InitializeAsync()
    {
        await _db.StartAsync();
        _factory = new WebApplicationFactory<Program>()
            .WithWebHostBuilder(b => b.ConfigureServices(s =>
            {
                s.RemoveAll<DbContextOptions<AppDbContext>>();
                s.AddDbContext<AppDbContext>(o => o.UseNpgsql(_db.GetConnectionString()));
            }));
        _client = _factory.CreateClient();
        // Apply migrations
        using var scope = _factory.Services.CreateScope();
        await scope.ServiceProvider.GetRequiredService<AppDbContext>().Database.MigrateAsync();
    }

    [Fact]
    public async Task CreateOrder_ReturnsCreated()
    {
        var cmd = new { CustomerId = Guid.NewGuid(), Items = new[] { new { ProductId = Guid.NewGuid(), Quantity = 1 } } };
        var response = await _client.PostAsJsonAsync("/api/orders", cmd);
        response.StatusCode.Should().Be(HttpStatusCode.Created);
    }

    public Task DisposeAsync() => _factory.DisposeAsync().AsTask();
}

// MyApp.ArchitectureTests/LayeringTests.cs
public class LayeringTests
{
    [Fact]
    public void Domain_ShouldNotReference_ExternalProjects()
    {
        var result = Types.InAssembly(typeof(BaseEntity).Assembly)
            .ShouldNot().HaveDependencyOn("MyApp.Application")
            .And().ShouldNot().HaveDependencyOn("MyApp.Infrastructure")
            .And().ShouldNot().HaveDependencyOn("MyApp.Api")
            .GetResult();

        result.IsSuccessful.Should().BeTrue();
    }

    [Fact]
    public void Application_ShouldNotReference_InfrastructureOrApi()
    {
        var result = Types.InAssembly(typeof(CreateOrderHandler).Assembly)
            .ShouldNot().HaveDependencyOn("MyApp.Infrastructure")
            .And().ShouldNot().HaveDependencyOn("MyApp.Api")
            .GetResult();

        result.IsSuccessful.Should().BeTrue();
    }
}
